add_filter('posts_search',function($search,$query){if(!$query->get('pt_search'))return $search;global $wpdb;$parts=[];foreach(array_slice(preg_split('/\s+/',trim($query->get('s'))),0,8) as $word){$like='%'.$wpdb->esc_like($word).'%';$parts[]=$wpdb->prepare("({$wpdb->posts}.post_title LIKE %s OR {$wpdb->posts}.post_content LIKE %s OR EXISTS (SELECT 1 FROM {$wpdb->postmeta} pm WHERE pm.post_id={$wpdb->posts}.ID AND pm.meta_key='_sku' AND pm.meta_value LIKE %s) OR EXISTS (SELECT 1 FROM {$wpdb->term_relationships} tr INNER JOIN {$wpdb->term_taxonomy} tt ON tr.term_taxonomy_id=tt.term_taxonomy_id INNER JOIN {$wpdb->terms} t ON tt.term_id=t.term_id WHERE tr.object_id={$wpdb->posts}.ID AND t.name LIKE %s))",$like,$like,$like,$like);}return $parts?' AND '.implode(' AND ',$parts):'';},10,2);
