function pt_term_image($t){$id=get_term_meta($t->term_id,'thumbnail_id',true);if($id)return wp_get_attachment_image_url($id,'large');$f=get_term_meta($t->term_id,'pt_image',true);return str_starts_with($f,'http')?$f:pt_asset($f?:'machinery.webp');}
function pt_sample_query(){return pt_local()?[]:['relation'=>'OR',['key'=>'_pt_sample','compare'=>'NOT EXISTS'],['key'=>'_pt_sample','value'=>'1','compare'=>'!=']];}
function pt_faq_posts($path=''){
 if(!$path)$path=wp_parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH);
 $all=get_posts(['post_type'=>'pt_faq','numberposts'=>-1,'orderby'=>'menu_order ID','order'=>'ASC']);
 if(is_page('faq')){$topic=sanitize_title($_GET['topic']??'');return array_filter($all,function($p)use($topic){return $topic?has_term($topic,'pt_topic',$p):!get_post_meta($p->ID,'_pt_page',true);});}
 if(is_tax('product_cat')){$term=get_queried_object();while($term->parent)$term=get_term($term->parent,'product_cat');$path='/products/'.$term->slug.'/';}
 if(is_singular('product')){$terms=wp_get_post_terms(get_the_ID(),'product_cat');if($terms&&!is_wp_error($terms)){$term=$terms[0];while($term->parent)$term=get_term($term->parent,'product_cat');$path='/products/'.$term->slug.'/';}}
 $specific=array_filter($all,function($p)use($path){return get_post_meta($p->ID,'_pt_page',true)===$path;});
 if($specific)return $specific;
 return array_filter($all,function($p){return !get_post_meta($p->ID,'_pt_page',true);});
}
function pt_faq($path=''){$rows=pt_faq_posts($path);if(!$rows)return;echo '<section class="pale"><div class="wrap faq"><div><span class="eyebrow">A FEW USEFUL ANSWERS</span><h2>Frequently Asked Questions</h2></div><div>';foreach($rows as $p)echo '<details><summary>'.esc_html($p->post_title).'</summary>'.wp_kses_post($p->post_content).'</details>';echo '</div></div></section>';}
function pt_icon($slug){static $icons;if(!$icons)$icons=json_decode(file_get_contents(get_template_directory().'/icons.json'),true);return $icons[$slug]['svg']??'<svg aria-hidden="true" viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor"><rect x="4" y="4" width="16" height="16" rx="3"/><path d="M8 8h8M8 12h8M8 16h5"/></svg>';}
function pt_range_description($slug){static $icons;if(!$icons)$icons=json_decode(file_get_contents(get_template_directory().'/icons.json'),true);return $icons[$slug]['description']??'';}
function pt_relevant_categories(){
 $map=['pharmaceutical'=>['cleanroom','medical-healthcare','ppe-safety'],'healthcare'=>['medical-healthcare','furniture-workplace','ppe-safety'],'construction'=>['building-infrastructure','industrial-products','ppe-safety'],'manufacturing'=>['industrial-products','machinery-automation','warehouse-logistics'],'corporate'=>['furniture-workplace','industrial-products'],'hospitality'=>['furniture-workplace','machinery-automation','warehouse-logistics'],'logistics'=>['warehouse-logistics','industrial-products','ppe-safety'],'education'=>['furniture-workplace','medical-healthcare'],'government'=>['furniture-workplace','building-infrastructure','warehouse-logistics'],'oem-odm'=>['furniture-workplace','industrial-products','warehouse-logistics'],'product-development'=>['furniture-workplace','industrial-products','machinery-automation'],'quality-control'=>['furniture-workplace','building-infrastructure','machinery-automation']];
 return $map[get_post_field('post_name',get_queried_object_id())]??[];
