add_action('wp_head',function(){
 $graph=[];$path=wp_parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH);
 if(!is_front_page()){$crumbs=[];foreach(pt_breadcrumb_items() as $i=>$c)$crumbs[]=['@type'=>'ListItem','position'=>$i+1,'name'=>$c['name'],'item'=>$c['url']];$graph[]=['@type'=>'BreadcrumbList','itemListElement'=>$crumbs];}
 if(is_front_page()||is_tax('product_cat')||is_singular(['product','pt_service','pt_industry'])||is_page(['faq','products','about-us','contact'])){$faq=[];foreach(pt_faq_posts($path) as $p){$faq[]=['@type'=>'Question','name'=>$p->post_title,'acceptedAnswer'=>['@type'=>'Answer','text'=>wp_strip_all_tags($p->post_content)]];}if($faq)$graph[]=['@type'=>'FAQPage','mainEntity'=>$faq];}
 if($graph)echo '<script type="application/ld+json">'.wp_json_encode(['@context'=>'https://schema.org','@graph'=>$graph],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT).'</script>';
