function pt_cards($posts){echo '<div class="product-grid">';foreach($posts as $p){$id=is_object($p)?$p->ID:(int)$p;$product=wc_get_product($id);if(!$product)continue;$sample=get_post_meta($id,'_pt_sample',true);echo '<article class="sample-card"><a class="product-photo" href="'.esc_url(get_permalink($id)).'">';if(has_post_thumbnail($id))echo get_the_post_thumbnail($id,'medium',['loading'=>'lazy']);else echo '<span aria-hidden="true">◇</span><small>'.($sample?'Sample product · image pending':'Product image pending').'</small>';echo '</a><div class="sample-copy">'.($sample?'<span class="sample-label">SAMPLE PRODUCT</span>':'').'<h3><a href="'.esc_url(get_permalink($id)).'">'.esc_html($product->get_name()).'</a></h3><p>'.esc_html(wp_trim_words(wp_strip_all_tags(str_replace('</p>','</p> ',$product->get_description())),18)).'</p><div class="product-actions"><button class="btn" data-add="'.(int)$id.'" data-name="'.esc_attr($product->get_name()).'">Add to Quote</button><a class="text-link" href="'.esc_url(get_permalink($id)).'">View details</a></div></div></article>';}echo '</div>';}
function pt_category_grid($slugs=[]){echo '<div class="category-grid">';foreach(pt_cats() as $i=>$c){if($slugs&&!in_array($c->slug,$slugs,true))continue;echo '<article class="category-card"><img src="'.esc_url(pt_term_image($c)).'" alt="" loading="lazy"><div><span class="category-icon">'.pt_icon($c->slug).'</span><h3><a href="'.esc_url(get_term_link($c)).'">'.esc_html($c->name).'</a></h3><p>'.esc_html(get_term_meta($c->term_id,'pt_short',true)?:wp_trim_words($c->description,10)).'</p></div></article>';}echo '</div>';}
function pt_breadcrumb_items(){
 $items=[['name'=>'Home','url'=>home_url('/')]];
 if(is_tax('product_cat')||is_singular('product')){
  $items[]=['name'=>'Products & Solutions','url'=>home_url('/products/')];
  $term=is_tax('product_cat')?get_queried_object():null;
  if(!$term){$terms=wp_get_post_terms(get_queried_object_id(),'product_cat');if(!is_wp_error($terms)&&$terms){usort($terms,function($a,$b){return count(get_ancestors($b->term_id,'product_cat'))<=>count(get_ancestors($a->term_id,'product_cat'));});$term=$terms[0];}}
  if($term){foreach(array_reverse(get_ancestors($term->term_id,'product_cat')) as $id){$t=get_term($id,'product_cat');$items[]=['name'=>$t->name,'url'=>get_term_link($t)];}$items[]=['name'=>$term->name,'url'=>get_term_link($term)];}
 }
 if(!is_tax('product_cat'))$items[]=['name'=>is_singular()?get_the_title(get_queried_object_id()):wp_get_document_title(),'url'=>home_url(wp_parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH))];
 return $items;
}
function pt_breadcrumb(){echo '<nav class="wrap breadcrumb" aria-label="Breadcrumb">';$items=pt_breadcrumb_items();foreach($items as $i=>$item){if($i)echo ' / ';echo $i===count($items)-1?esc_html($item['name']):'<a href="'.esc_url($item['url']).'">'.esc_html($item['name']).'</a>';}echo '</nav>';}
function pt_heading(){return is_tax()?single_term_title('',false):(is_post_type_archive()?(pt_archive_value('h1')?:post_type_archive_title('',false)):get_the_title());}
