 $id=get_queried_object_id();$title=wp_get_document_title();$canonical=is_singular()?get_permalink():(is_tax()?get_term_link(get_queried_object()):home_url(wp_parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH)));$override=is_singular()?get_post_meta($id,'_pt_canonical',true):'';if(is_tax('product_cat'))$override=get_term_meta($id,'pt_canonical',true);if(is_post_type_archive())$override=pt_archive_value('canonical');if($override)$canonical=$override;if(is_tax() && get_query_var('paged')>1 && !isset($_GET['filter']))$canonical=get_pagenum_link(get_query_var('paged'));
 $desc=is_tax('product_cat')?get_term_meta($id,'pt_description',true):get_post_meta($id,'_pt_description',true);if(is_post_type_archive())$desc=pt_archive_value('description');if(!$desc)$desc=is_singular()?wp_trim_words(wp_strip_all_tags(get_post_field('post_content',$id)),28):'PANDATEC: Singapore B2B sourcing, procurement and product solutions.';
 $img=is_singular()?get_post_meta($id,'_pt_social_image',true):'';if(is_tax('product_cat'))$img=get_term_meta($id,'pt_social_image',true);if(is_post_type_archive())$img=pt_archive_value('image');if(!$img)$img=get_the_post_thumbnail_url($id,'large')?:pt_asset('p_about.webp');
 echo '<meta name="description" content="'.esc_attr($desc).'"><link rel="canonical" href="'.esc_url($canonical).'"><meta property="og:title" content="'.esc_attr($title).'"><meta property="og:description" content="'.esc_attr($desc).'"><meta property="og:url" content="'.esc_url($canonical).'"><meta property="og:image" content="'.esc_url($img).'"><meta property="og:type" content="website"><meta name="twitter:card" content="summary_large_image">';
 $graph=[['@type'=>'Organization','@id'=>home_url('/#organization'),'name'=>'PANDATEC PTE. LTD.','url'=>home_url('/'),'telephone'=>'+65 8472 6456','email'=>'info@pandatec.sg','address'=>['@type'=>'PostalAddress','streetAddress'=>'35 Tannery Road #05-06, Ruby Industrial Complex','postalCode'=>'347740','addressCountry'=>'SG']]];
 if(is_singular('product')&&!get_post_meta($id,'_pt_sample',true)){$p=wc_get_product($id);$v=['@type'=>'Product','name'=>$p->get_name(),'description'=>wp_strip_all_tags($p->get_description()),'url'=>get_permalink()];if($p->get_sku())$v['sku']=$p->get_sku();if(has_post_thumbnail($id))$v['image']=get_the_post_thumbnail_url($id,'large');$graph[]=$v;}
 if(is_singular('post'))$graph[]=['@type'=>'Article','headline'=>get_the_title(),'datePublished'=>get_the_date('c'),'dateModified'=>get_the_modified_date('c'),'author'=>['@type'=>'Organization','name'=>'PANDATEC']];
 echo '<script type="application/ld+json">'.wp_json_encode(['@context'=>'https://schema.org','@graph'=>$graph],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT).'</script>';
