function pt_supply_links($category='',$product_id=0){
 $mapping=['furniture-workplace'=>['corporate','hospitality','education','government'],'industrial-products'=>['manufacturing','logistics','construction'],'building-infrastructure'=>['construction','government'],'medical-healthcare'=>['healthcare','pharmaceutical','education'],'cleanroom'=>['pharmaceutical','manufacturing','healthcare'],'ppe-safety'=>['construction','manufacturing','healthcare','pharmaceutical'],'warehouse-logistics'=>['logistics','manufacturing','hospitality'],'machinery-automation'=>['manufacturing','hospitality','logistics']];
 $industries=$product_id?wp_get_object_terms($product_id,'pt_application',['fields'=>'slugs']):($mapping[$category]??[]);$services=$product_id?wp_get_object_terms($product_id,'pt_support',['fields'=>'slugs']):['global-sourcing','oem-odm','quality-control','singapore-delivery'];if(!$industries&&!$services)return;
 echo '<section><div class="wrap content-grid">';foreach(['Applications / Industries'=>[$industries,'industries','pt_industry'],'Our Supply Support'=>[$services,'services','pt_service']] as $title=>[$slugs,$base,$type]){if(!$slugs)continue;echo '<article><h2>'.esc_html($title).'</h2><ul>';foreach($slugs as $slug){$p=get_page_by_path($slug,OBJECT,$type);if($p)echo '<li><a class="text-link" href="'.esc_url(get_permalink($p)).'">'.esc_html(str_replace('Supply Solutions for ','',$p->post_title)).'</a></li>';}echo '</ul></article>';}echo '</div></section>';
}
function pt_related_projects($slug,$tax='pt_topic'){$posts=get_posts(['post_type'=>'pt_project','numberposts'=>3,'tax_query'=>[['taxonomy'=>$tax,'field'=>'slug','terms'=>$slug]]]);if(!$posts)return;echo '<section><div class="wrap"><h2>Related Projects</h2><div class="content-grid">';foreach($posts as $p)echo '<article><h3><a href="'.esc_url(get_permalink($p)).'">'.esc_html($p->post_title).'</a></h3><p>'.esc_html(wp_trim_words(wp_strip_all_tags($p->post_content),25)).'</p></article>';echo '</div></div></section>';}
add_action('wp_head',function(){if(is_front_page()){echo '<link rel="preload" as="image" href="'.esc_url(pt_asset('p_about.webp')).'">';$graph=[['@type'=>'LocalBusiness','name'=>'PANDATEC PTE. LTD.','url'=>home_url('/'),'image'=>pt_asset('logo_black.png'),'telephone'=>'+65 8472 6456','address'=>['@type'=>'PostalAddress','streetAddress'=>'35 Tannery Road #05-06, Ruby Industrial Complex','addressLocality'=>'Singapore','postalCode'=>'347740','addressCountry'=>'SG'],'openingHoursSpecification'=>[['@type'=>'OpeningHoursSpecification','dayOfWeek'=>['Monday','Tuesday','Wednesday','Thursday','Friday'],'opens'=>'09:00','closes'=>'18:00']]],['@type'=>'WebSite','name'=>'PANDATEC','url'=>home_url('/'),'potentialAction'=>['@type'=>'SearchAction','target'=>home_url('/?s={search_term_string}'),'query-input'=>'required name=search_term_string']]];echo '<script type="application/ld+json">'.wp_json_encode(['@context'=>'https://schema.org','@graph'=>$graph],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT).'</script>';}});

function pt_filter_topics($taxonomy,$key,$label){$terms=get_terms(['taxonomy'=>$taxonomy,'hide_empty'=>false]);if(is_wp_error($terms)||!$terms)return;echo '<form method="get" class="filter-form"><label>'.esc_html($label).' <select name="'.esc_attr($key).'"><option value="">All</option>';foreach($terms as $term)echo '<option value="'.esc_attr($term->slug).'" '.selected(sanitize_title($_GET[$key]??''),$term->slug,false).'>'.esc_html($term->name).'</option>';echo '</select></label><button class="btn">Apply filter</button></form>';}
