add_filter('the_content',function($content){if(!is_singular('post')||!in_the_loop()||!is_main_query())return $content;$links=[];$i=0;$content=preg_replace_callback('/<h2([^>]*)>(.*?)<\/h2>/is',function($m)use(&$links,&$i){$i++;$id='article-section-'.$i;$links[]='<li><a href="#'.$id.'">'.esc_html(wp_strip_all_tags($m[2])).'</a></li>';return '<h2 id="'.$id.'"'.$m[1].'>'.$m[2].'</h2>';},$content);return ($links?'<nav aria-label="Article contents"><h2>In this article</h2><ol>'.implode('',$links).'</ol></nav>':'').$content;});

