// Review-only screens and local wording must never leak into a production render.
add_action('template_redirect',function(){
 if(pt_local())return;
 if(is_page('review')||is_page('layout-check')){global $wp_query;$wp_query->set_404();status_header(404);nocache_headers();}
 ob_start(function($html){
  $html=str_replace('Local enquiry confirmation','Enquiry received',$html);
  $html=str_replace('Your saved reference is displayed in this browser after submission. Local test enquiries are stored for staff review; notifications are captured on this computer and are not sent externally.','Your enquiry has been recorded. We will contact you using the details provided. Keep the reference shown below for follow-up.',$html);
  $html=str_replace('Local review data','Privacy notice',$html);
  $html=str_replace('This test website runs on this computer. Quote selections are saved in your browser. Contact details, requirements and selected attachments submitted through the local enquiry form are stored in the local test database and are accessible to authorised test staff accounts.','This page is a placeholder until PANDATEC approves the final privacy notice, including the information collected, purpose and legal basis, recipients, retention period, user rights, contact details and any international transfers.',$html);
  $html=str_replace('No email is delivered externally. Use fictional contact details and non-sensitive test files. You can remove browser quote selections using the quote list. The site owner can remove stored test enquiries before staging.','Do not publish the site until the approved legal wording has been inserted and the enquiry form consent text has been checked against it.',$html);
  return $html;
 });
});
